import{z as E,x as k,o as t,c as l,q as d,j as n,D as o,d as c,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"tiktoken / BPE 实现","description":"","frontmatter":{"title":"tiktoken / BPE 实现","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tiktoken.md","filePath":"llm/tiktoken.md","lastUpdated":1791063341000}'),s={name:"llm/tiktoken.md"};function A(p,e,B,P,_,m){const a=k("Mermaid");return t(),l("div",null,[e[2]||(e[2]=d('<h1 id="tiktoken-bpe-实现" tabindex="-1">tiktoken / BPE 实现 <a class="header-anchor" href="#tiktoken-bpe-实现" aria-label="Permalink to &quot;tiktoken / BPE 实现&quot;">​</a></h1><div class="epigraph"><p>GPT 家族把文本收成 UTF-8 字节再做字节对编码；tiktoken 把这套已冻结的词表做成可在生产路径上每秒吃掉数 GB 的确定性编码器。</p><footer>—— 对照 Sennrich et al. 的 BPE、Radford et al. 的 GPT-2 字节级切分，以及 OpenAI 的 tiktoken 实现</footer></div><p>Gage 1994 年把字节对编码写成压缩算法；Sennrich、Haddow 与 Birch 2016 年把它变成 NMT 的稀有词方案：从字符表出发，反复合并语料里最频的相邻对。Radford 等人的 GPT-2 再把起点换成 256 个 UTF-8 字节，彻底消灭 UNK，并用一条正则预切分避免把无关片段焊在一起。OpenAI 的 tiktoken 不重新发明这套数学，它解决的是另一件事：在 API、计费、上下文闸门和本地推理里，对 <code>r50k_base</code>、<code>p50k_base</code>、<code>cl100k_base</code>、<code>o200k_base</code> 给出与模型训练时<strong>逐 id 一致</strong>且比 Hugging Face 当时的 Python 快路径快三到六倍的实现。SentencePiece 是可训练的实验室工具；tiktoken 是冻结编码表上的生产编码器。把二者当成「都是 BPE」而互换，是上下文溢出和账单对不上的常规原因。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练可以用任意慢的切分；服务不行。提示可能是数万字符的 JSON 与日志，网关必须在 GPU 看见矩阵之前用与权重相同的规则算出 token 数，否则 <code>--max-input-tokens</code> 是假的。Python 里每次构造 <code>AutoTokenizer</code>、走慢速循环合并，会在高并发下把 CPU 变成第二条延迟曲线。更糟的是多套「近似 GPT-2」词表：有的用 SentencePiece 空白符号，有的用 <code>Ġ</code> 前缀，有的正则略不同，同一句相差几个 token，聊天模板再叠一层，用户看到的「8k 上下文」与模型真实窗口错位。</p><p>字节级 BPE 自己的问题是：若从原始字节直接合并、不做预切分，空格、字母、标点会焊成稀奇古怪的跨类符号，词表被网页噪声污染。GPT-2 用正则先切出「大致像词」的片段，再在片段内做 BPE，这是预分词与无损字节回退的折中。tiktoken 把这条正则、合并秩表和特殊 token（<code>&lt;|endoftext|&gt;</code>、FIM、<code>&lt;|im_start|&gt;</code> 等）打包成名为 encoding 的对象。问题变成：如何让所有语言的绑定、所有网关进程，加载的是同一张秩表，而不是「看起来差不多的 100k 词表」。</p><p><span class="marginnote">术语翻译：BPE 就是「先把文本拆成 256 个字节，再反复合并语料里最常见的相邻字节对」的算法，合并的先后顺序记成秩表。给新文本编码时，按秩表从最早学会的合并开始贪心执行——所以词表本质不是「词典」，是一份合并操作的优先级清单。</span></p><h3 id="编码表是模型的一部分" tabindex="-1">编码表是模型的一部分 <a class="header-anchor" href="#编码表是模型的一部分" aria-label="Permalink to &quot;编码表是模型的一部分&quot;">​</a></h3><p><code>cl100k_base</code> 服务 GPT-4 / GPT-3.5-turbo / <code>text-embedding-ada-002</code>；<code>p50k_base</code> 服务 Codex 与 <code>text-davinci-002/003</code>；<code>r50k_base</code> 即 GPT-2/GPT-3 davinci 系；较新的旗舰与 <code>gpt-4o</code> 一类走 <code>o200k_base</code>（词表约 20 万）。<code>encoding_for_model(name)</code> 存在的理由，就是禁止业务代码写死一种 encoding。<span class="marginnote">聊天接口的账单 token 还包含模板与特殊符，不等于对用户可见字符串跑一遍 <code>encode</code>。用 tiktoken 在本地估算 API 费用，必须复现同样的 message 组装，否则会系统性低估。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>推理期 BPE 不扫描全局语料。给定预切分后的字节串，编码器反复把当前相邻对里、合并秩最高（训练时最早合并、秩最小）的一对焊成词表项，直到不能再合。实现上用哈希表存 <code>mergeable_ranks</code>，用正则 <code>pat_str</code> 预切分，特殊 token 走单独词典、可在 <code>encode</code> 时允许或拒绝。decode 把 id 映回字节再解 UTF-8；流式时必须缓冲不完整码点，不能对半个汉字的 id 单独 <code>decode</code> 成替换符。OpenAI 公开的 Python 包核心是 Rust，官方 README 称在 1GB 文本、GPT-2 词表上比当时 <code>GPT2TokenizerFast</code> 快 3–6 倍。教育子模块 <code>SimpleBytePairEncoding</code> 可从 <code>cl100k_base</code> 可视化合并，便于对照论文算法，但生产路径不要用它。</p><p><span class="marginnote">常见误区：流式输出时对每个 id 单独 decode，会在汉字或 emoji 被拆成两个 token 的边界上打出乱码替换符。正确做法是按字节缓冲、凑齐完整 UTF-8 码点再解码——这不是 bug，是字节级分词的必然契约。</span></p><p>扩展编码的合法方式是复制 <code>pat_str</code> 与 <code>mergeable_ranks</code>，只改 <code>special_tokens</code> 并换新名字（例如为对话加上 <code>&lt;|im_start|&gt;</code>）。私自改合并表却沿用 <code>cl100k_base</code> 这个名字，会造成静默的 id 错位。插件机制 <code>tiktoken_ext</code> 用于注册自定义 Encoding，让 <code>get_encoding</code> 能找到它。tiktoken <strong>不提供</strong> 在新语料上重训 100k 词表的 API；要训练应回到 SentencePiece、Hugging Face tokenizers 或自写 BPE，再把秩表导出成与 tiktoken 兼容的结构——那是另一条供应链。</p>',13)),(t(),n(r,null,{default:o(()=>[i(a,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22UTF-8%20%E6%96%87%E6%9C%AC%22%5D%20--%3E%20RE%5B%22%E6%AD%A3%E5%88%99%E9%A2%84%E5%88%87%E5%88%86%22%5D%0A%20%20RE%20--%3E%20BY%5B%22%E5%AD%97%E8%8A%82%E5%BA%8F%E5%88%97%22%5D%0A%20%20BY%20--%3E%20MG%5B%22%E6%8C%89%20mergeable_ranks%20%E8%B4%AA%E5%BF%83%E5%90%88%E5%B9%B6%22%5D%0A%20%20SP%5B%22%E7%89%B9%E6%AE%8A%20token%20%E8%A1%A8%22%5D%20--%3E%20ID%5B%22token%20id%22%5D%0A%20%20MG%20--%3E%20ID%0A%20%20ID%20--%3E%20DEC%5B%22%E5%AD%97%E8%8A%82%E6%8B%BC%E6%8E%A5%22%5D%0A%20%20DEC%20--%3E%20UTF%5B%22%E5%AE%8C%E6%95%B4%20UTF-8%20%E7%A0%81%E7%82%B9%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h3 id="预切分正则决定「什么叫相邻」" tabindex="-1">预切分正则决定「什么叫相邻」 <a class="header-anchor" href="#预切分正则决定「什么叫相邻」" aria-label="Permalink to &quot;预切分正则决定「什么叫相邻」&quot;">​</a></h3><p>BPE 只在预切分块内部合并。正则若把字母与紧跟的标点切开，<code>&#39;s</code> 与 <code>end-to-end</code> 的焊法就变了；若允许跨空格合并，词表会出现带前导空格的词片，GPT-2 用 <code>Ġ</code> 表示这种空格。cl100k 相对 r50k 加大词表、调整正则，对多语言与代码更省长度，但不是「更智能的分词器」——只是另一张冻结合并表。o200k 继续加大覆盖。评估「这个 tokenizer 好不好」应看：目标语料的平均 token/字节、尾部语言是否碎、特殊符是否够用，而不是看名字里的数字。Sennrich 的原论文在词级预分词上训练；字节级方案删掉了 UNK，也把噪声字节放进词表，脏语料直接变成脏合并。</p><p><span class="marginnote">同一模型家族在不同 API 名下可能换 encoding。硬编码 <code>cl100k_base</code> 去数 <code>gpt-4o</code> 的上下文，闸门会偏。应用应调用 <code>encoding_for_model</code>，并在集成测试里锁一句多语言加代码的探针，断言 id 序列哈希不变。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>训练期 BPE 估计的是语料上的贪心压缩：频繁共现的字节块变成原子，交叉熵在更短序列上计算。推理期算法是确定性的查表，不再有「更新合并」。这与 Unigram 不同：Unigram 在推理仍可采样切分，tiktoken 路径没有概率。确定性使 KV 缓存、前缀复用和计费可复现。正则预切分把「空格、字母、数字、标点」的类型边界写进归纳偏置，减少跨类型垃圾合并，代价是语言相关——为英语设计的正则对无空格文字主要靠字节块，中文往往更碎，同样字符预算下中文有效上下文更短。这是编码表的政治，不是 bug。</p>',5)),(t(),n(r,null,{default:o(()=>[i(a,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20C%5B%22%E8%AE%AD%E7%BB%83%E6%9C%9F%3A%20%E6%89%AB%E6%8F%8F%E8%AF%AD%E6%96%99%22%5D%20--%3E%20F%5B%22%E7%BB%9F%E8%AE%A1%E7%9B%B8%E9%82%BB%E5%AD%97%E8%8A%82%E5%AF%B9%E9%A2%91%E6%AC%A1%22%5D%0A%20%20F%20--%3E%20M%5B%22%E5%90%88%E5%B9%B6%E6%9C%80%E9%AB%98%E9%A2%91%E5%AF%B9%2C%20%E5%86%99%E5%85%A5%E7%A7%A9%E8%A1%A8%22%5D%0A%20%20M%20--%3E%20LOOP%7B%22%E8%BE%BE%E5%88%B0%E8%AF%8D%E8%A1%A8%E4%B8%8A%E9%99%90%3F%22%7D%0A%20%20LOOP%20--%3E%7C%22%E5%90%A6%22%7C%20F%0A%20%20LOOP%20--%3E%7C%22%E6%98%AF%22%7C%20FR%5B%22%E5%86%BB%E7%BB%93%20mergeable_ranks%22%5D%0A%20%20FR%20--%3E%20I%5B%22%E6%8E%A8%E7%90%86%E6%9C%9F%3A%20%E5%8F%AA%E6%9F%A5%E8%A1%A8%E8%B4%AA%E5%BF%83%E5%90%88%E5%B9%B6%22%5D%0A%20%20I%20--%3E%20D%5B%22%E5%90%8C%E8%BE%93%E5%85%A5%E5%BF%85%E5%BE%97%E5%90%8C%20id%3A%20%E7%A1%AE%E5%AE%9A%E6%80%A7%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">数字实例：cl100k 下英文平均约 4 个字符折 1 个 token，常见汉字往往 1 字就要 1 到 2 个 token——同样写 500 字的提示，中文可能折成七八百个 token，同样的窗口预算，中文能装下的有效内容明显更短。数预算只能靠真正 encode。</span></p><p>相对 SentencePiece：空白处理（<code>▁</code> vs 字节/ <code>Ġ</code>）、规范化（NFKC FST vs 几乎不做兼容折叠）、训练（现场训 vs 冻结表）、UNK 策略（字符 UNK vs 字节回退）全都不兼容。Llama 2 用 SentencePiece，对它跑 tiktoken 的 cl100k 再喂模型，等于用错误词表解码权重。服务框架必须把 tokenizer 工件与 checkpoint 当成同一版本号。</p><h3 id="速度来自实现-正确性来自表" tabindex="-1">速度来自实现，正确性来自表 <a class="header-anchor" href="#速度来自实现-正确性来自表" aria-label="Permalink to &quot;速度来自实现，正确性来自表&quot;">​</a></h3><p>3–6 倍来自 Rust、少分配、预编译正则与避免 Python 循环，不是来自近似算法。任何「更快但不保证 id 一致」的分词器都不能替换 tiktoken 去对 OpenAI 模型。本地开源模型若宣称兼容 GPT-4 tokenizer，应以 tiktoken 的 id 序列为金标准做差分，而不是只比词表大小。FIM 特殊符、<code>&lt;|endofprompt|&gt;</code> 是否允许进入普通 <code>encode</code>，会改变补全与对话的边界；默认拒绝特殊符、显式允许白名单，是安全默认。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>tiktoken 不训练、不解决词表污染、不自动升级。新语言或领域要降 token/字节，只能换一张表并重训模型。decode 在错误 id 或截断字节上的行为必须当成 API 契约测试。多进程各自加载大 rank 表会涨 RSS，应共享内存或在 router 进程集中分词（TGI 把 tokenizer 放在 router 一侧就是这个原因）。教育模块与生产 Encoding 混用会把慢路径带进热路径。开源复现 GPT 时，若无法获得完全相同的 <code>mergeable_ranks</code>，就不要声称 token 级兼容。</p><p>计费与长度闸门还要加上模板。只对用户文本 <code>encode</code> 会漏掉系统提示与工具 schema。嵌入模型 <code>text-embedding-ada-002</code> 与聊天模型共享 cl100k，不代表截断策略相同。o200k 的 20 万词表加大嵌入矩阵，对小模型是显存税，对多语言是长度收益——选表是模型设计，不是预处理细节。</p><p><span class="marginnote">不要在请求热路径里 <code>get_encoding</code> 失败再联网。编码表应随应用分发。也不要用字符数、单词数或「中文除以 1.5」去近似；闸门必须在真正 encode 之后。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tiktoken 是 OpenAI 冻结 BPE 编码表的高速确定性实现，不是通用训练器。</li><li>算法谱系：Gage 压缩 → Sennrich 子词 BPE → GPT-2 字节级加正则预切分。</li><li>常用表：<code>r50k</code> / <code>p50k</code> / <code>cl100k</code> / <code>o200k</code>，必须按模型名解析，不能写死。</li><li>预切分正则定义相邻关系；特殊符与聊天模板计入真实 token。</li><li>与 SentencePiece 的空白、规范化、UNK 策略不兼容，权重与 tokenizer 必须同版本。</li><li>生产路径用官方 Encoding；流式 decode 要缓冲不完整 UTF-8。</li><li>出处：Sennrich et al.，ACL 2016；Radford et al.，GPT-2，2019；OpenAI，tiktoken 代码库；对照 Kudo &amp; Richardson SentencePiece。</li></ul>',10))])}const T=E(s,[["render",A]]);export{g as __pageData,T as default};
